/* From Uiverse.io by SouravBandyopadhyay - Tags: simple, 3d, action, red, button, switch, input, toggle switch */
.__UIV_SCOPE__ .toggle-button-cover {
  display: inline-block;
  position: relative;
  width: 200px;
  height: 140px;
  box-sizing: border-box;
}

.__UIV_SCOPE__ .button-cover:before {
  counter-increment: button-counter;
  content: counter(button-counter);
  position: absolute;
  right: 0;
  bottom: 0;
  color: #d7e3e3;
  font-size: 12px;
  line-height: 1;
  padding: 5px;
}

.__UIV_SCOPE__ .button-cover,
.__UIV_SCOPE__ .knobs,
.__UIV_SCOPE__ .layer {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
}

.__UIV_SCOPE__ .button {
  position: relative;
  top: 50%;
  width: 74px;
  height: 36px;
  margin: -20px auto 0 auto;
  overflow: hidden;
}

.__UIV_SCOPE__ .button.r,
.__UIV_SCOPE__ .button.r .layer {
  border-radius: 100px;
}

.__UIV_SCOPE__ .checkbox {
  position: relative;
  width: 100%;
  height: 100%;
  padding: 0;
  margin: 0;
  opacity: 0;
  cursor: pointer;
  z-index: 3;
}

.__UIV_SCOPE__ .knobs {
  z-index: 2;
}

.__UIV_SCOPE__ .layer {
  width: 100%;
  background-color: #ebf7fc;
  transition: 0.3s ease all;
  z-index: 1;
}

.__UIV_SCOPE__ #button-2 .knobs:before,
.__UIV_SCOPE__ #button-2 .knobs:after {
  content: 'YES';
  position: absolute;
  top: 4px;
  left: 4px;
  width: 20px;
  height: 10px;
  color: #fff;
  font-size: 10px;
  font-weight: bold;
  text-align: center;
  line-height: 1;
  padding: 9px 4px;
  background-color: #03f480;
  border-radius: 50%;
  transition: 0.3s ease all;
}

.__UIV_SCOPE__ #button-2 .knobs:before {
  content: 'YES';
}

.__UIV_SCOPE__ #button-2 .knobs:after {
  content: 'NO';
}

.__UIV_SCOPE__ #button-2 .knobs:after {
  right: -28px;
  left: auto;
  background-color: #f44336;
}

.__UIV_SCOPE__ #button-2 .checkbox:checked + .knobs:before {
  left: -28px;
}

.__UIV_SCOPE__ #button-2 .checkbox:checked + .knobs:after {
  right: 4px;
}

.__UIV_SCOPE__ #button-2 .checkbox:checked ~ .layer {
  background-color: #fcebeb;
}
